    ("deny", "contractor", "article:publish"),
]

def permitted(roles, action):
    matches = [p for p in POLICY if p[1] in roles and p[2] == action]
    if any(effect == "deny" for effect, _, _ in matches):
        return False
    return any(effect == "allow" for effect, _, _ in matches)

