import fnmatch

RULES = [
    ("/admin/*", "deny"),
    ("/admin/health", "allow"),
    ("/*", "allow"),
]

def decide(path):
    for pattern, effect in RULES:
        if fnmatch.fnmatch(path, pattern):
            return effect
    return "deny"

print(decide("/admin/health"))

